async () => {
  const zones = await cloudflare.request({ method: "GET", path: "/zones", query: { per_page: 50 } });
  const list = (zones.result || []).map(z => ({ name: z.name, id: z.id, status: z.status }));
  const zone = list.find(z => z.name === "codewhale.net");
  if (!zone) return { list, note: "codewhale.net zone not found" };
  const end = new Date(); const start30 = new Date(end.getTime() - 30*86400e3); const start7 = new Date(end.getTime() - 7*86400e3);
  const d = x => x.toISOString().slice(0,10);
  const q1 = `{ viewer { zones(filter:{zoneTag:"${zone.id}"}) {
    daily: httpRequests1dGroups(limit:31, filter:{date_geq:"${d(start30)}", date_leq:"${d(end)}"}, orderBy:[date_ASC]) { dimensions{date} uniq{uniques} sum{requests pageViews bytes} }
  } } }`;
  const q2 = `{ viewer { zones(filter:{zoneTag:"${zone.id}"}) {
    paths: httpRequestsAdaptiveGroups(limit:15, filter:{datetime_geq:"${start7.toISOString()}", datetime_leq:"${end.toISOString()}", requestSource:"eyeball"}, orderBy:[count_DESC]) { count dimensions{clientRequestPath} }
    install: httpRequestsAdaptiveGroups(limit:31, filter:{datetime_geq:"${start30.toISOString()}", datetime_leq:"${end.toISOString()}", clientRequestPath:"/install.sh"}, orderBy:[date_ASC]) { count dimensions{date} }
    geo: httpRequestsAdaptiveGroups(limit:10, filter:{datetime_geq:"${start7.toISOString()}", datetime_leq:"${end.toISOString()}", requestSource:"eyeball"}, orderBy:[count_DESC]) { count dimensions{clientCountryName} }
  } } }`;
  const r1 = await cloudflare.request({ method: "POST", path: "/graphql", body: { query: q1 } });
  const r2 = await cloudflare.request({ method: "POST", path: "/graphql", body: { query: q2 } });
  return { zone, list, r1: r1.result ?? r1, r2: r2.result ?? r2 };
}

async () => {
  const zoneId = "ff30aecdf72f97ec6cd034d6de823cf2";
  const end = new Date(); const d = x => x.toISOString().slice(0,10);
  const out = {};
  const tryQ = async (name, q) => { try { const r = await cloudflare.request({ method:"POST", path:"/graphql", body:{query:q} }); out[name] = r.result ?? r; } catch(e) { out[name] = "ERR: " + (e.message||e); } };
  for (const days of [7, 3, 1]) {
    const s = new Date(end.getTime() - days*86400e3);
    await tryQ(`daily_${days}d`, `{ viewer { zones(filter:{zoneTag:"${zoneId}"}) { httpRequests1dGroups(limit:31, filter:{date_geq:"${d(s)}", date_leq:"${d(end)}"}, orderBy:[date_ASC]) { dimensions{date} uniq{uniques} sum{requests pageViews} } } } }`);
    if (!String(out[`daily_${days}d`]).startsWith("ERR")) break;
  }
  const s1 = new Date(end.getTime() - 86400e3);
  await tryQ("paths_1d", `{ viewer { zones(filter:{zoneTag:"${zoneId}"}) { httpRequestsAdaptiveGroups(limit:15, filter:{datetime_geq:"${s1.toISOString()}", datetime_leq:"${end.toISOString()}"}, orderBy:[count_DESC]) { count dimensions{clientRequestPath} } } } }`);
  await tryQ("geo_1d", `{ viewer { zones(filter:{zoneTag:"${zoneId}"}) { httpRequestsAdaptiveGroups(limit:8, filter:{datetime_geq:"${s1.toISOString()}", datetime_leq:"${end.toISOString()}"}, orderBy:[count_DESC]) { count dimensions{clientCountryName} } } } }`);
  return out;
}

async () => {
  const zoneId = "ff30aecdf72f97ec6cd034d6de823cf2";
  const end = new Date(); const s1 = new Date(end.getTime() - 86400e3);
  const out = {};
  const tryQ = async (name, q) => { try { const r = await cloudflare.request({ method:"POST", path:"/graphql", body:{query:q} }); out[name] = r.result ?? r; } catch(e) { out[name] = "ERR: " + (e.message||e); } };
  for (const p of ["/install.sh", "/v1/telemetry", "/api/sync/version", "/install.ps1"]) {
    await tryQ(p, `{ viewer { zones(filter:{zoneTag:"${zoneId}"}) { httpRequestsAdaptiveGroups(limit:1, filter:{datetime_geq:"${s1.toISOString()}", datetime_leq:"${end.toISOString()}", clientRequestPath:"${p}"}) { count } } } }`);
  }
  await tryQ("sync_version_by_ua", `{ viewer { zones(filter:{zoneTag:"${zoneId}"}) { httpRequestsAdaptiveGroups(limit:10, filter:{datetime_geq:"${s1.toISOString()}", datetime_leq:"${end.toISOString()}", clientRequestPath:"/api/sync/version"}, orderBy:[count_DESC]) { count dimensions{userAgent} } } } }`);
  await tryQ("telemetry_by_ua", `{ viewer { zones(filter:{zoneTag:"${zoneId}"}) { httpRequestsAdaptiveGroups(limit:10, filter:{datetime_geq:"${s1.toISOString()}", datetime_leq:"${end.toISOString()}", clientRequestPath:"/v1/telemetry"}, orderBy:[count_DESC]) { count dimensions{userAgent} } } } }`);
  // where do routes go
  try { const w = await cloudflare.request({ method:"GET", path:`/accounts/${accountId}/workers/scripts` }); out.workers = (w.result||[]).map(x=>x.id); } catch(e) { out.workers = "ERR "+e.message; }
  try { const r = await cloudflare.request({ method:"GET", path:`/zones/${zoneId}/workers/routes` }); out.routes = r.result; } catch(e) { out.routes = "ERR "+e.message; }
  try { const dns = await cloudflare.request({ method:"GET", path:`/zones/${zoneId}/dns_records`, query:{per_page:50} }); out.dns = (dns.result||[]).map(r=>`${r.type} ${r.name} -> ${r.content}`); } catch(e) { out.dns = "ERR "+e.message; }
  return out;
}

